        @if($entry->status === 'draft' && $entry->submitted_at)<form wire:submit="returnForReview"><label>Reason to return for review<input class="erp-input" wire:model="reason" minlength="5" maxlength="500" required></label><button class="erp-button secondary">Return for review</button></form>@endif
